<script lang="ts">
  import { viewedMeeting as meeting, viewedRecord as record, viewedState as stateValue, viewedEvents as recordEvents, language, configs, settings } from '../../lib/stores';
  import { exportOne, exportAll, saveRecordState, deleteRecords } from '../../lib/api';
  import { toast } from '../../lib/toast';
  import { runBusy, busyKeys } from '../../lib/busy';
  import { t, dateTime, timeOnly, confirmDialog } from '../../lib/ui';
  import { filterRowsByTag, eventTypeCounts, deriveHandEntries, handEntryActionLabel } from '../../lib/record-tools';
  import { deriveReactionLog, perPersonCounts, yesSince } from '../../lib/reactions';
import { getLiveStatusLabel, getMatchStatusLabel, getParticipantLocationLabel, getRecordSourceLabel } from '../../lib/session-labels';
  import ExportMenu from '../../lib/common/ExportMenu.svelte';
  import RecordNameEditor from '../../lib/common/RecordNameEditor.svelte';
  import { recordTitle } from '../../lib/record-title';
  import StatusBadge from '../../lib/common/StatusBadge.svelte';
  import { statusLabel, statusStyle } from '../../lib/status-style';
  import NameMatchingPanel from '../../lib/NameMatchingPanel.svelte';
  import SortableFilterStack from '../../lib/common/SortableFilterStack.svelte';
  import AttendanceFilterPanel from '../../lib/common/AttendanceFilterPanel.svelte';
  import { nextRecordSort, sortRecordRows, type RecordSortDir, type RecordSortKey } from '../../lib/record-sort';
  import { groupLabel } from '../../lib/group-label';
  import { cameraCell, micCell, audioMarker, cameraTooltip, micTooltip, cameraStateLabel } from '../../lib/media-labels';
  import Tooltip from '../../lib/common/Tooltip.svelte';
import { eventMatchesSearch } from '../../lib/event-search';
  import ProofGallery from '../../lib/ProofGallery.svelte';
  $: titleParts = recordTitle({ ...$meeting, customName: $stateValue.customName });
  let tab = 'attendance';
  let subtab = 'status';
  let status = '';
  let search = '';
  let checkInTime = '';
  let selectedEventTypes: string[] = [];
  let eventTypesInitialized = false;
  const eventTypeKeys = ['joinedBefore','join','leave','waitingRoomJoinFromOutside','waitingRoomJoinFromMeeting','waitingRoomJoinedBefore','waitingRoomLeave'];
  let ascending = true;
  let filteredRows: any[] = [];
  let sortKey: RecordSortKey | '' = '';
  let sortDir: RecordSortDir = 'asc';
  $: movement = $record.record?.movementEvents || $record.movementEvents || [];
  $: names = $record.record?.nameChangeEvents || $record.nameChangeEvents || [];
  $: allRows = $record.rows || [];
  $: attendanceRows = allRows.filter((row: any) => !['unmatched', 'guest'].includes(row.matchStatus));
  $: profile = ($configs.profiles || []).find((item: any) => item.id === ($record.record?.selectedProfileId || $record.record?.guessedProfileId)) || ($configs.profiles || []).find((item: any) => item.id === 'default-all');
  $: durationMinutes = Number($record.durationMinutes ?? $record.record?.durationMinutes ?? 0);
  $: durationWhole = Math.max(0, Math.floor(durationMinutes));
  $: durationText = `${String(Math.floor(durationWhole / 60)).padStart(2, '0')}:${String(durationWhole % 60).padStart(2, '0')}`;
  $: manualCount = $stateValue.manualSnapshots?.length || 0;
  $: decisionCount = $stateValue.reconciliationDecisions?.length || 0;
  $: unmatchedCount = allRows.filter((row: any) => row.matchStatus === 'unmatched').length;
  $: guestCount = allRows.filter((row: any) => row.matchStatus === 'guest').length;
  $: exportedAt = $record.record?.exportedAt || $stateValue.exportedAt || $meeting?.exportedAt;
  $: mode = $record.mode || 'generic';
  // Imported AttendFlow records carry no privilege data: show a dash and no notes.
  $: privilege = $record.privilege || null;
  $: privilegeTimes = (privilege?.intervals || []).map((i: any) => `${timeOnly(i.from).slice(0,5)}–${timeOnly(i.to).slice(0,5)}`).join(', ');
  $: privilegeNote = privilege?.intervals?.length ? t(`等候室数据仅在你担任主持人或联合主持人期间记录：${privilegeTimes}。其余时间等候室中的人员和等候时长不会被记录。`, `Waiting-room data is only recorded while you are host or co-host: ${privilegeTimes}. Outside those times, people in the waiting room and their waiting time are not recorded.`) : t('你在本场会议中不是主持人或联合主持人，等候室中的人员和等候时长未被记录。','You were not host or co-host in this meeting, so people in the waiting room and their waiting time were not recorded.');
  $: groupNames = [...new Set<string>([...($configs.groups || []).map((g: any) => typeof g === 'string' ? g : g.name || g.group), ...($configs.roster || []).map((p: any) => p.group)].filter(Boolean))];
  $: rows = sortRecordRows(filteredRows, sortKey, sortDir);
  $: if (!eventTypesInitialized && movement.length) { selectedEventTypes = [...eventTypeKeys]; eventTypesInitialized = true; }
  $: events = movement.filter((event: any) => selectedEventTypes.includes(event.type || event.eventType) && eventMatchesSearch(event, allRows, search)).slice().sort((a: any,b: any) => Date.parse(b.timestamp)-Date.parse(a.timestamp));
  $: handEntries = deriveHandEntries($recordEvents);
  $: reactionEntries = deriveReactionLog($recordEvents, [], $language);
  $: reactionCounts = perPersonCounts(reactionEntries);
  $: startDate = $meeting?.startedAt ? new Date($meeting.startedAt) : new Date();
  $: checkInTime ||= `${String(startDate.getHours()).padStart(2, '0')}:${String(startDate.getMinutes()).padStart(2, '0')}`;
  $: checkInSince = new Date(startDate.getFullYear(), startDate.getMonth(), startDate.getDate(), Number(checkInTime.slice(0,2)), Number(checkInTime.slice(3,5))).getTime();
  $: checkedIn = yesSince(reactionEntries, checkInSince);
  $: searchedReactions = reactionEntries.filter((entry: any) => eventMatchesSearch({ screenName: entry.name, userId: entry.userId }, allRows, search)).slice().sort((a: any,b: any) => Number(b.at)-Number(a.at));
  $: counts = eventTypeCounts(movement);
  $: searchedNames = names.filter((item: any) => eventMatchesSearch(item, allRows, search)).slice().sort((a: any,b: any) => Date.parse(b.timestamp || b.at)-Date.parse(a.timestamp || a.at));
  $: searchedHands = handEntries.filter((entry: any) => eventMatchesSearch(entry, allRows, search)).slice().sort((a: any,b: any) => Date.parse(b.timestamp)-Date.parse(a.timestamp));
  $: primary = [['overview','概况','Overview'],['attendance','自动考勤','Auto Attendance'],['events','进出记录','Entry/Exit'],['hands','举手记录','Raise Hand'],['reactions','反应与反馈','Reactions & feedback'],['snapshots','手动考勤记录','Manual Attendance Records'], ...(($stateValue.proofCaptures?.length || 0) ? [['proof','截图证明','Proof']] : [])];
  const secondary = [['status','状态','Status'],['matching','昵称匹配','Name Matching'],['profile','考勤配置','Attendance Profile'],['names','名称变更','Name Changes']];
  const statusDefs = [['seen','到过','Seen','seen'],['full_present','全程','Full Present','fullPresent'],['late','迟到','Late','late'],['returned','返回','Returned','returned'],['left_early','早退','Left Early','leftEarly'],['missing','缺席','Absent','missing'],['ignored','不计入','Ignored','ignored'],['total','总计','Total','total']];
  $: statItems = statusDefs.map((d: any) => ({ id:d[0], label:t(d[1],d[2]), color:statusStyle(d[0]).color, count:d[0] === 'total' ? ($record.summary?.total ?? attendanceRows.length) : ($record.summary?.[d[3]] ?? filterRowsByTag(attendanceRows,d[0]).length) })).filter((item: any) => item.id === 'total' || item.count > 0);
  $: if (status && !statItems.some((item: any) => item.id === status)) status = '';
  const statusPriority = ['left_early','late','returned','full_present','seen','missing','ignored','guest','unmatched'];
  function recordStatusTags(row: any) { const tags = [...new Set<string>(row.tags || [])].filter((tag) => !['ignored','guest','unmatched'].includes(tag)); return (tags.includes('full_present') ? tags.filter((tag) => tag !== 'seen') : tags).sort((a,b) => statusPriority.indexOf(a)-statusPriority.indexOf(b)); }
  const movementLabels: Record<string, string[]> = { joinedBefore:['启动时已加入','Already in meeting at startup'], join:['进入会议','Joined meeting'], leave:['离开会议','Left meeting'], waitingRoomJoinFromOutside:['进入等候室','Entered waiting room'], waitingRoomJoinFromMeeting:['移至等候室','Moved to waiting room'], waitingRoomJoinedBefore:['启动时已在等候室','In waiting room at startup'], waitingRoomLeave:['离开等候室','Left waiting room'] };
  function label(pair: string[]) { return t(pair[1], pair[2]); }
  function eventName(type: string) { const pair = movementLabels[type]; return pair ? t(pair[0], pair[1]) : t('未知','Unknown'); }
  async function changeMode(value: string) { await runBusy('record-mode', async () => { try { await saveRecordState({ mode: value }, 'viewed'); } catch (error: any) { toast.error(`${t('保存失败：', 'Save failed: ')}${error.message}`); } }); }
  async function handleExport(kind: string) { await runBusy('record-export', async () => { try { if (kind === 'all') await exportAll('viewed'); else await exportOne(kind, 'viewed'); toast.success(t('导出成功。','Export succeeded.')); } catch (error: any) { toast.error(`${t('导出失败：','Export failed: ')}${error.message}`); } }); }
  function toggleSort(key: RecordSortKey) { const next = nextRecordSort({ key: sortKey, dir: sortDir }, key); sortKey = next.key; sortDir = next.dir; }
  function sortAria(key: RecordSortKey) { return sortKey !== key ? 'none' : sortDir === 'asc' ? 'ascending' : 'descending'; }
  function sortIndicator(key: RecordSortKey) { return sortKey !== key ? '↕' : sortDir === 'asc' ? '↑' : '↓'; }
  async function handleDelete() {
    if (!$meeting?.endedAt || !(await confirmDialog({ title: t('删除考勤记录','Delete Attendance Record'), message: t('确定删除此会议记录吗？此操作无法撤销。','Delete this meeting record? This cannot be undone.'), destructive: true }))) return;
    await runBusy('record-delete', async () => { try {
      await deleteRecords([$meeting.instanceId], 'viewed');
      toast.success(t('考勤记录已删除。','Attendance record deleted.'));
    } catch (error: any) { toast.error(`${t('删除失败：','Delete failed: ')}${error.message}`); } });
  }
</script>

<section class="detail">
  {#if $record.loading}<p class="empty">{t('加载中…','Loading…')}</p>{:else}
  <div class="header">
    <div class="title"><div class="title-line"><h2>{titleParts.primary}</h2><RecordNameEditor target="viewed" customName={$stateValue.customName || ""} /></div>{#if titleParts.secondary}<small class="title-secondary">{titleParts.secondary}</small>{/if}<div class="badges"><span>{$record.mode === 'roster' ? t('花名册','Roster') : t('普通模式','Generic')}</span><span>{getRecordSourceLabel($meeting?.source || 'meeting_live',$language as any).label}</span><small>{$meeting?.meetingNumber} · {$record.summary?.total ?? attendanceRows.length} {t('位参与者','participants')}</small></div></div>
    <div class="actions"><ExportMenu disabled={$busyKeys.has('record-export')} labels={{ all:t('导出全部','Export All'), json:t('导出 JSON','Export JSON'), attendance:t('导出考勤 CSV','Export Attendance CSV'), manual:t('导出手动记录 CSV','Export Manual Records CSV') }} onExport={handleExport}/><button class="danger" disabled={!$meeting?.endedAt || $busyKeys.has('record-delete')} onclick={handleDelete}>{$busyKeys.has('record-delete') ? t('删除中…','Deleting…') : t('删除','Delete')}</button></div>
  </div>
  <div class="record-tabs" role="tablist" aria-label={t('记录详情','Record detail')}>{#each primary as item}<button role="tab" aria-selected={tab===item[0]} class:active={tab===item[0]} onclick={() => {tab=item[0];search='';status='';}}>{label(item)}{#if item[0]==='attendance'}<small>{$record.summary?.total ?? ($record.rows || []).length}</small>{:else if item[0]==='events'}<small>{movement.length}</small>{:else if item[0]==='hands'}<small>{handEntries.length}</small>{:else if item[0]==='reactions'}<small>{reactionEntries.length}</small>{:else if item[0]==='snapshots'}<small>{$stateValue.manualSnapshots?.length || 0}</small>{/if}</button>{/each}</div>
  {#if tab==='attendance'}
    <div class="secondary" role="tablist" aria-label={t('自动考勤标签','Auto Attendance tabs')}>{#each secondary as item}<button role="tab" aria-selected={subtab===item[0]} class:active={subtab===item[0]} onclick={() => subtab=item[0]}>{label(item)}</button>{/each}</div>
    {#if subtab==='status'}
      <div class="summary-row"><SortableFilterStack items={statItems} active={status} onSelect={(id) => status = status === id ? '' : id} /></div>
      <div class="mode-row"><b>{t('出席情况','Attendance Status')}</b><div class="segmented"><button disabled={$busyKeys.has('record-mode')} class:chosen={$record.mode!=='roster'} onclick={() => changeMode('generic')}>{t('普通模式','Generic')}</button><button disabled={$busyKeys.has('record-mode')} class:chosen={$record.mode==='roster'} onclick={() => changeMode('roster')}>{t('花名册','Roster')}</button></div></div>
      <AttendanceFilterPanel rows={attendanceRows} roster={$configs.roster || []} configGroups={groupNames} {profile} {mode} language={$language} initiallyOpen={!$settings.filterDefaultsClosed} activeFilter={status} bind:ascending onActiveFilterChange={(value) => status = value} onRows={(value) => filteredRows = value} />
      <div class="table-wrap"><table><thead><tr><th>#</th><th aria-sort={sortAria('name')}><button type="button" class="sort-header" onclick={() => toggleSort('name')}>{t('姓名','Name')} <span class:active={sortKey === 'name'}>{sortIndicator('name')}</span></button></th><th>{t('状态','Status')}</th><th aria-sort={sortAria('score')}><button type="button" class="sort-header" onclick={() => toggleSort('score')}>{t('出勤率','Score')} <span class:active={sortKey === 'score'}>{sortIndicator('score')}</span></button></th><th>{t('标签','Tags')}</th><th>{t('分组','Group')}</th><th>{t('姓名匹配','Name Match')}</th><th aria-sort={sortAria('firstJoin')}><button type="button" class="sort-header" onclick={() => toggleSort('firstJoin')}>{t('首次加入','First Join')} <span class:active={sortKey === 'firstJoin'}>{sortIndicator('firstJoin')}</span></button></th><th aria-sort={sortAria('minutes')}><button type="button" class="sort-header" onclick={() => toggleSort('minutes')}>{t('分钟','Minutes')} <span class:active={sortKey === 'minutes'}>{sortIndicator('minutes')}</span></button></th><th aria-sort={sortAria('camera')}><Tooltip text={cameraTooltip($language)}><button type="button" class="sort-header" onclick={() => toggleSort('camera')}>{t('摄像头','Camera')} <span class:active={sortKey === 'camera'}>{sortIndicator('camera')}</span></button></Tooltip></th><th aria-sort={sortAria('mic')}><Tooltip text={micTooltip($language)}><button type="button" class="sort-header" onclick={() => toggleSort('mic')}>{t('麦克风','Mic')} <span class:active={sortKey === 'mic'}>{sortIndicator('mic')}</span></button></Tooltip></th></tr></thead><tbody>{#each rows as row,i}<tr><td>{i+1}</td><td class="participant-name"><b>{row.canonicalName || row.zoomName}</b><small>{row.pinyin || row.zoomNames?.join(', ')}</small></td><td><div class='tag-list'>{#each recordStatusTags(row) as chip}<StatusBadge status={chip === 'missing' ? 'absent' : chip} label={statusLabel(chip === 'missing' ? 'absent' : chip,$language)} />{/each}</div></td><td><span class="score" class:score-high={(row.score || 0)>=95} class:score-mid={(row.score || 0)>=80 && (row.score || 0)<95} class:score-low={(row.score || 0)<80}>{Math.round(row.score || 0)}%</span></td><td><div class="tag-list">{#each (row.tags || []).filter((chip: string) => chip !== 'total' && chip !== 'ignored' && chip !== 'unmatched') as chip}<StatusBadge status={chip} label={statusLabel(chip,$language)} />{/each}</div></td><td class="group-cell" title={groupLabel(row.group, $language)}>{groupLabel(row.group, $language)}</td><td>{#if row.matchStatus === 'matched' || row.canonicalName}<StatusBadge label={t('已关联','Matched')} tone="success" />{:else}—{/if}</td><td>{row.firstJoinAt ? timeOnly(row.firstJoinAt) : '—'}</td><td>{Math.round(row.totalPresenceMinutes || 0)}</td><td class="media-cell">{cameraCell(row, $language).text}</td><td class="media-cell">{micCell(row, $language)}{#if audioMarker(row, $language)}<span class="audio-marker">{audioMarker(row, $language)}</span>{/if}</td></tr>{:else}<tr><td colspan="11" class="empty">{t('没有符合条件的参与者','No matching participants')}</td></tr>{/each}</tbody></table></div>
    {:else if subtab==='matching'}<NameMatchingPanel rows={$record.rows || []} decisions={$stateValue.reconciliationDecisions || []} roster={$configs.roster || []} aliases={$configs.aliases || []} nameChanges={names} language={$language} readOnly={true}/>
    {:else if subtab==='profile'}<div class="meta-grid"><article><small>{t('所选配置','Selected profile')}</small><b>{profile?.name || t('未设定','Not Set')}</b></article><article><small>{t('迟到阈值','Late threshold')}</small><b>{$record.record?.lateAfterMinutes ?? '—'} {t('分钟','min')}</b></article><article><small>{t('返回窗口','Return window')}</small><b>{$record.record?.returnWindowMinutes ?? '—'} {t('分钟','min')}</b></article><article><small>{t('包含分组','Included groups')}</small><b>{($record.record?.selectedIncludedSubgroups || []).join(', ') || t('全部','All')}</b></article></div>
    {:else}<h3>{t('名称变更','Name Changes')} · {names.length}</h3><p class="description">{t('记录参与者在会议期间更改的名称。','Tracks participant name changes during the meeting.')}</p><div class="toolbar"><input placeholder={t('旧名、新名或拼音','Old/new name or pinyin')} bind:value={search}/></div>{#if searchedNames.length}<div class="table-wrap"><table><thead><tr><th>{t('时间','Time')}</th><th>{t('旧名称','Previous Name')}</th><th>{t('新名称','New Name')}</th></tr></thead><tbody>{#each searchedNames as item}<tr><td>{timeOnly(item.timestamp || item.at)}</td><td>{item.previousScreenName || item.previous_screen_name || '—'}</td><td>{item.nextScreenName || item.next_screen_name || '—'}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">{names.length ? t('没有符合搜索条件的名称变更。','No name changes match your search.') : t('暂无名称变更记录。','No name changes recorded yet.')}</p>{/if}{/if}
  {:else if tab==='overview'}{#if privilege && !privilege.coveredWholeMeeting}<p class="privilege-note">{privilegeNote}</p>{/if}<h3>{t('会议信息','Meeting Metadata')}</h3><div class="meta-grid">{#each [[t('会议号','Meeting ID'),$meeting?.meetingNumber || '—'],[t('开始时间','Start'),$meeting?.startedAt ? dateTime($meeting.startedAt) : '—'],[t('结束时间','End'),$meeting?.endedAt ? dateTime($meeting.endedAt) : t('进行中','In Progress')],[t('时长','Duration'),durationText],[t('主持权限','Host Privilege'),!privilege?'—':privilege.current==='host'?t('主持人','Host'):privilege.current==='cohost'?t('联合主持人','Co-host'):t('无','None')],[t('权限获取时间','Privilege Acquired'),!privilege?'—':privilege.acquiredAt?timeOnly(privilege.acquiredAt):t('未获得','Not acquired')],[t('使用的配置','Profile Used'),profile?.name || t('未设定','Not Set')],[t('数据来源','Record Source'),getRecordSourceLabel($meeting?.source || 'meeting_live',$language as any).label],[t('版本号','Revision'),$record.record?.revision ?? '—'],[t('导出状态','Export Status'),exportedAt ? `${t('已导出','Exported')} ${dateTime(exportedAt)}` : t('待导出','Pending Export')],[t('会议 UUID','Meeting UUID'),$record.record?.meetingUUID || $record.record?.meetingUuid || $meeting?.meetingUUID || $meeting?.meetingUuid || $meeting?.uuid || '—']] as card}<article><small>{card[0]}</small><b>{card[1]}</b></article>{/each}</div><h3>{t('操作记录','Operator Actions')}</h3><div class="meta-grid">{#each [[t('手动考勤记录','Manual Attendance Records'),manualCount],[t('名单匹配记录','Matching Decisions'),decisionCount],[t('进出记录','Entry/Exit'),movement.length],[t('未匹配','Unmatched'),unmatchedCount],[t('来宾','Guests'),guestCount]] as card}<article><small>{card[0]}</small><b>{card[1]}</b></article>{/each}</div>
  {:else if tab==='proof'}<ProofGallery captures={$stateValue.proofCaptures || []} instanceId={$meeting?.instanceId || ''} />
  {:else if tab==='events'}{#if privilege && !privilege.coveredWholeMeeting}<p class="privilege-note">{privilegeNote}</p>{/if}<div class="toolbar"><input aria-label={t('搜索事件','Search events')} placeholder={t('搜索姓名或拼音','Search by name or pinyin')} bind:value={search}/><button onclick={() => {search='';selectedEventTypes=[...eventTypeKeys]}}>{t('清除筛选','Clear Filters')}</button></div><div class="filter-chips">{#each eventTypeKeys as type}<button class:active={selectedEventTypes.includes(type)} aria-pressed={selectedEventTypes.includes(type)} onclick={() => selectedEventTypes=selectedEventTypes.includes(type)?selectedEventTypes.filter((v)=>v!==type):[...selectedEventTypes,type]}>{eventName(type)} · {counts[type] || 0}</button>{/each}</div>{#if events.length}<div class="table-wrap"><table><thead><tr><th>{t('时间','Time')}</th><th>{t('姓名','Name')}</th><th>{t('事件类型','Event Type')}</th></tr></thead><tbody>{#each events as event}<tr><td>{timeOnly(event.timestamp)}</td><td>{event.participant?.screenName || '—'}</td><td>{eventName(event.type || event.eventType)}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">{movement.length ? t('没有符合筛选条件的事件。','No matching events.') : t('暂无事件记录。','No events recorded yet.')}</p>{/if}
  {:else if tab==='hands'}<h3>{t('举手事件','Raise Hand Events')} · {handEntries.length}</h3><div class="toolbar"><input placeholder={t('搜索姓名或拼音','Search by name or pinyin')} bind:value={search}/></div>{#each searchedHands as entry}<article class="event"><time>{dateTime(entry.timestamp)}</time><b>{entry.screenName}</b><span>{handEntryActionLabel(entry, $language)}</span></article>{:else}<p class="empty">{handEntries.length ? t('没有符合搜索条件的记录。','No records matching your search.') : t('没有举手记录','No raise hand records')}</p>{/each}<h3>{t('举手快照','Raise Hand Captures')}</h3>{#each $stateValue.raiseHandCaptures || [] as capture}<article class="event"><time>{dateTime(capture.timestamp)}</time><b>{capture.totalCount}</b><span>{(capture.screenNames || []).join(', ')}</span></article>{/each}
  {:else if tab==='reactions'}<h3>{t('反应与反馈','Reactions & feedback')} · {reactionEntries.length}</h3><p class="description">{t('应用连接前设置的反馈不可见（参与者列表不含此信息）。','Feedback set before the app connected is not visible (the participant list does not include it).')}</p><section class="meta-grid"><article><label>{t('从…起回答“是”的人','Answered Yes since')} <input aria-label={t('开始时间','Start time')} type="time" bind:value={checkInTime}/></label><b>{t(`${checkedIn.length} 人`, `${checkedIn.length} ${checkedIn.length === 1 ? 'person' : 'people'}`)}{checkedIn.length ? `${t('：', ': ')}${checkedIn.join(t('、', ', '))}` : ''}</b></article></section><h3>{t('每人计数','Counts per person')}</h3><div class="table-wrap"><table><thead><tr><th>{t('姓名','Name')}</th><th>{t('反馈计数','Feedback counts')}</th><th>{t('反应','Reactions')}</th></tr></thead><tbody>{#each reactionCounts as person}<tr><td>{person.name}</td><td>{Object.entries(person.feedback).map(([type,count]) => `${deriveReactionLog([{kind:'feedback',type}], [], $language)[0]?.label}: ${count}`).join(' · ')}</td><td>{person.reactions}</td></tr>{:else}<tr><td colspan="3" class="empty">{t('暂无反馈或反应','No feedback or reactions yet')}</td></tr>{/each}</tbody></table></div><h3>{t('记录','Log')} · {reactionEntries.length}</h3><div class="toolbar"><input aria-label={t('搜索姓名或拼音','Search by name or pinyin')} placeholder={t('搜索姓名或拼音','Search by name or pinyin')} bind:value={search}/></div>{#each searchedReactions as entry}<article class="event"><time>{timeOnly(entry.at)}</time><b>{entry.name}</b><span>{entry.label}</span></article>{:else}<p class="empty">{t('没有符合搜索条件的记录。','No matching records.')}</p>{/each}
  {:else}{#each ($stateValue.manualSnapshots || []).slice().reverse() as snapshot}<details><summary>{dateTime(snapshot.timestamp)} · {snapshot.participants?.length || 0}</summary><div class="table-wrap"><table><thead><tr><th>{t('姓名','Name')}</th><th>{t('参与者 ID','Participant ID')}</th><th>{t('位置','Location')}</th><th>{t('匹配状态','Match Status')}</th><th>{t('摄像头','Camera')}</th></tr></thead><tbody>{#each snapshot.participants || [] as participant}<tr><td>{participant.screenName}</td><td>{participant.participantUUID || participant.sessionParticipantId || '—'}</td><td>{getParticipantLocationLabel(participant.location,$language as any) || '—'}</td><td>{getMatchStatusLabel(participant.matchStatus,$language as any)}</td><td>{cameraStateLabel(participant.videoOn, $language)}</td></tr>{/each}</tbody></table></div></details>{:else}<p class="empty">{t('尚无手动考勤记录','No manual attendance records yet')}</p>{/each}{/if}
  {/if}
</section>
 <style>
