-accent)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px}.table-wrap table{width:100%;min-width:780px;border-collapse:collapse;font-size:11px}.table-wrap th{background:#f5f6fa;color:#536071;font-size:9px;letter-spacing:.3px;text-transform:uppercase;text-align:left}.sort-header{border:0;background:transparent;padding:0;color:inherit;font:inherit;cursor:pointer}.sort-header:hover{color:var(--accent)}.sort-header span{color:var(--muted)}.sort-header span.active{color:var(--accent)}.table-wrap th,.table-wrap td{padding:8px 9px;border-bottom:1px solid var(--line)}.table-wrap tr:last-child td{border-bottom:0}.table-wrap td:nth-child(2) b,.table-wrap td:nth-child(2) small{display:block}.table-wrap td:nth-child(2) small{color:var(--muted);font-size:9px}.table-wrap .participant-name{max-width:260px;white-space:normal;overflow-wrap:anywhere}.table-wrap .participant-name b,.table-wrap .participant-name small{overflow-wrap:anywhere}.table-wrap .group-cell{max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.score{border-radius:15px;background:#e6fffa;color:#0782a7;padding:4px 8px;font-size:10px;font-weight:700}.score.score-high{background:#ecfdf5;color:#15803d}.score.score-mid{background:#ecfeff;color:#0369a1}.score.score-low{background:#fffbeb;color:#b45309}.tag-list{display:flex;gap:4px;flex-wrap:wrap}.event{display:flex;align-items:center;gap:14px;padding:8px 4px;border-bottom:1px solid var(--line);font-size:11px}.event time{color:var(--muted);min-width:145px}.event span{margin-left:auto;color:var(--muted)}.meta-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px}.meta-grid article{border:1px solid var(--line);border-radius:7px;padding:10px;display:grid;gap:5px;font-size:11px}.meta-grid small,.empty{color:var(--muted)}.empty{text-align:center;padding:20px;font-size:11px}h3{font-size:12px;margin:12px 0 6px}details{padding:8px;border-bottom:1px solid var(--line)}summary{font-size:11px;cursor:pointer}
.filter-chips{display:flex;gap:6px;flex-wrap:wrap;margin:6px 0 9px}.filter-chips button{min-height:26px;padding:4px 8px;border:1px solid var(--line);border-radius:16px;background:white;color:#596273;font-size:10px}.filter-chips button.active{border-color:#aac4f5;background:#edf4ff;color:#245caa}.description{font-size:11px;color:var(--muted);margin:4px 0 8px}.media-cell{white-space:nowrap;color:var(--muted)}.audio-marker{display:inline-block;margin-left:6px;padding:1px 6px;border-radius:10px;background:var(--surface-soft);border:1px solid var(--line);font-size:10px;color:var(--muted)}.title-line{display:flex;align-items:center;gap:4px;min-width:0;margin-bottom:6px}.title-line h2{margin:0;min-width:0;overflow-wrap:anywhere}.title-secondary{display:block;margin:-2px 0 7px;font-size:12px;color:var(--muted)}</style>
